import React, { useState } from "react";
import { predict } from "../api";

// Example lists — replace these with your real model categories
const INDUSTRIES = [
  { label: "Technology", value: 0 },
  { label: "Finance", value: 1 },
  { label: "Healthcare", value: 2 },
  { label: "Retail", value: 3 }
];

const COUNTRIES = [
  { label: "USA", value: 0 },
  { label: "Kenya", value: 1 },
  { label: "India", value: 2 },
  { label: "Germany", value: 3 }
];

export default function Predict() {
  const [formData, setFormData] = useState({
    industry_enc: 0,
    country_enc: 0,
    company_age: 5,
    avg_size: 50,
    current_employee_estimate: 50,
    total_employee_estimate: 50,
    model_type: "rf_category"
  });

  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: Number(value) }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setResult(null);

    const res = await predict(formData);
    setResult(res);
    setLoading(false);
  };

  return (
    <div style={{ padding: "20px", maxWidth: "700px", margin: "0 auto", fontFamily: "Arial, sans-serif" }}>
      <h1 style={{ textAlign: "center", color: "#333" }}>Company Growth Prediction</h1>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: "15px", marginTop: "20px" }}>
        
        {/* Industry Dropdown */}
        <div>
          <label>Industry:</label>
          <select name="industry_enc" value={formData.industry_enc} onChange={handleChange}>
            {INDUSTRIES.map((i) => (
              <option key={i.value} value={i.value}>{i.label}</option>
            ))}
          </select>
        </div>

        {/* Country Dropdown */}
        <div>
          <label>Country:</label>
          <select name="country_enc" value={formData.country_enc} onChange={handleChange}>
            {COUNTRIES.map((c) => (
              <option key={c.value} value={c.value}>{c.label}</option>
            ))}
          </select>
        </div>

        {/* Sliders for numeric fields */}
        <div>
          <label>Company Age: {formData.company_age} years</label>
          <input
            type="range"
            name="company_age"
            min="1"
            max="50"
            value={formData.company_age}
            onChange={handleChange}
          />
        </div>

        <div>
          <label>Average Company Size: {formData.avg_size}</label>
          <input
            type="range"
            name="avg_size"
            min="1"
            max="1000"
            value={formData.avg_size}
            onChange={handleChange}
          />
        </div>

        <div>
          <label>Current Employee Estimate: {formData.current_employee_estimate}</label>
          <input
            type="range"
            name="current_employee_estimate"
            min="1"
            max="1000"
            value={formData.current_employee_estimate}
            onChange={handleChange}
          />
        </div>

        <div>
          <label>Total Employee Estimate: {formData.total_employee_estimate}</label>
          <input
            type="range"
            name="total_employee_estimate"
            min="1"
            max="5000"
            value={formData.total_employee_estimate}
            onChange={handleChange}
          />
        </div>

        {/* Model Type Dropdown */}
        <div>
          <label>Model Type:</label>
          <select name="model_type" value={formData.model_type} onChange={handleChange}>
            <option value="rf_category">RF Category</option>
            <option value="rf_level">RF Level</option>
            <option value="xgb_category">XGB Category</option>
            <option value="xgb_level">XGB Level</option>
          </select>
        </div>

        <button type="submit" disabled={loading} style={{ padding: "10px", fontSize: "16px", backgroundColor: "#4CAF50", color: "white", border: "none", borderRadius: "5px" }}>
          {loading ? "Predicting..." : "Predict"}
        </button>
      </form>

      {/* Result */}
      {result && (
        <div style={{ marginTop: "20px", padding: "15px", border: "1px solid #ccc", borderRadius: "5px", backgroundColor: "#f7f7f7" }}>
          <h3>Prediction Result:</h3>
          <p><strong>Cluster:</strong> {result.cluster}</p>
          <p><strong>Prediction:</strong> {result.prediction}</p>
          <p><strong>Confidence:</strong> {(result.confidence * 100).toFixed(2)}%</p>
        </div>
      )}
    </div>
  );
}
